mapper.select:
select id, cfg_id, oa_dept_id, wx_dept_key as wx_dept_id,
       wx_parent_dept_key as wx_parent_dept_id, yx
from ${table}
where yx = 1 and cfg_id = #{cfgId}
order by id

select id from ${table}
where cfg_id = #{cfgId} and oa_dept_id = #{oaDeptId}
  and wx_dept_key = #{wxDeptId}
order by id

mapper.update:
update ${table}
set wx_dept_key = #{e.wxDeptId},
    wx_parent_dept_key = #{e.wxParentDeptId},
    yx = #{e.yx},
    remark = #{e.remark},
    modedatamodifier = #{e.modedatamodifier},
    modedatamodifydatetime = #{e.modedatamodifydatetime}
where id = #{e.id}
